with scored as (select id, session_id, event_type, event_time, duration_sec, avg(duration_sec) over (partition by event_type order by duration_sec, id rows between 6 preceding and current row) as duration_sec_avg_6, ntile(3) over (partition by event_type order by duration_sec desc, id) as duration_sec_bucket, avg(duration_sec) over (order by event_time, id rows between 3 preceding and current row) as duration_sec_avg_3 from web_events) select session_id, sum(case when event_type = 'purchase' then duration_sec else 0 end) as purchase_duration_sec, approx_percentile(duration_sec_avg_6, 0.9) as duration_sec_avg_6_p90, (unix_timestamp(max(event_time)) - unix_timestamp(min(event_time))) / 60 as duration_min from scored group by session_id order by duration_sec_avg_6_p90 desc nulls last
